return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mr','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'आपल्या WordPress फाइल्स आणि डेटाबेसचा आपल्या स्वतःच्या स्टोरेजमध्ये बॅकअप घेते — Dropbox, Google Drive, Cloudflare R2, Amazon S3 किंवा कोणत्याही S3-सुसंगत बकेटमध्ये — एकाच वेळी ते पुनर्संचयित करते, आणि इतर बॅकअप व स्थलांतर प्लगइन्सद्वारे तयार केलेले बॅकअप आयात करते.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'बॅकअप','Get Pro: schedules, several storages, encryption'=>'Pro मिळवा: वेळापत्रक, अनेक स्टोरेज, एन्क्रिप्शन','Working…'=>'काम सुरू आहे…','Finished'=>'पूर्ण झाले','Failed'=>'अपयशी झाले','Cancelled'=>'रद्द केले','Cancel'=>'रद्द करा','Restore'=>'पुनर्संचयित करा','Delete'=>'हटवा','Delete this backup from your storage? This cannot be undone.'=>'हा बॅकअप आपल्या स्टोरेजमधून हटवायचा? ही कृती पूर्ववत केली जाऊ शकत नाही.','No backups yet. Press “Back up now” to make the first one.'=>'अद्याप कोणतेही बॅकअप नाहीत. पहिला तयार करण्यासाठी "आता बॅकअप घ्या" दाबा.','Reading your storage…'=>'तुमचे स्टोरेज वाचत आहे…','a complete backup, as opposed to an incremental oneFull backup'=>'पूर्ण बॅकअप','a backup holding only what changed since an earlier oneIncremental backup'=>'इन्क्रिमेंटल बॅकअप','Encrypted'=>'कूटबद्ध केलेले','From another site'=>'दुसऱ्या साइटवरून','Database'=>'डेटाबेस','Files'=>'फायली','Uploading %1$s: %2$s%%'=>'%1$s अपलोड करत आहे: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'उघडलेल्या विंडोमध्ये Dropbox मध्ये साइन इन करा, नंतर Dropbox तुम्हाला दाखवत असलेला कोड पेस्ट करा:','Saved.'=>'जतन केले.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'हे गंतव्य प्लगइनमधून काढून टाकायचे? त्यामध्ये साठवलेले बॅकअप हटवले जात नाहीत.','Reload the page to see the restored site.'=>'पुनर्संचयित केलेली साइट पाहण्यासाठी पृष्ठ रीलोड करा.','Storage'=>'स्टोरेज','Import & migrate'=>'आयात आणि स्थलांतर करा','Settings'=>'सेटिंग्ज','Sections'=>'विभाग','Google Drive is connected.'=>'Google Drive जोडले गेले आहे.','Google Drive could not be connected.'=>'Google Drive कनेक्ट करता आले नाही.','Details'=>'तपशील','Back up now'=>'आता बॅकअप घ्या','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'बॅकअप तुमच्या स्वतःच्या स्टोरेजवर जातात, या सर्व्हरवर नाही. प्रथम <a href="%s">तुमचे स्टोरेज कनेक्ट करा</a>.','What to back up'=>'कशाचा बॅकअप घ्यायचा','Files and database'=>'फायली आणि डेटाबेस','Database only'=>'फक्त डेटाबेस','Files only'=>'फक्त फाइल्स','Note (optional)'=>'नोंद (पर्यायी)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'पुढील भाग तयार होण्यापूर्वी प्रत्येक भाग तुमच्या स्टोरेजवर अपलोड केला जातो आणि या सर्व्हरवरून काढून टाकला जातो, त्यामुळे बॅकअप तुमच्या होस्टिंगवर कधीही जागा व्यापत नाही.','Your backups'=>'तुमचे बॅकअप','Refresh'=>'रिफ्रेश करा','Restore this backup'=>'हा बॅकअप पुनर्संचयित करा','Passphrase'=>'पासफ्रेज','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'मला समजले आहे की हे या साइटच्या फाइल्स आणि डेटाबेस बॅकअपसह पुनर्स्थित करते. बॅकअपमध्ये नसलेल्या फाइल्स ठेवल्या जातात.','Recent activity'=>'अलीकडील क्रियाकलाप','Backup'=>'बॅकअप','Restore / import'=>'पुनर्संचयित करा / आयात करा','Running'=>'सुरू आहे','Your storage'=>'तुमचा स्टोरेज' . "\0" . 'तुमची स्टोरेज गंतव्ये','No storage yet. Choose where your backups go below.'=>'अद्याप कोणतेही स्टोरेज नाही. तुमचे बॅकअप कुठे जावेत ते खाली निवडा.','Ready'=>'तयार','Not connected'=>'कनेक्ट केलेले नाही','Connect'=>'कनेक्ट करा','Test'=>'चाचणी','Edit'=>'संपादित करा','Remove'=>'काढून टाका','Add storage'=>'स्टोरेज जोडा','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'बॅकअप एकाच स्टोरेज गंतव्यस्थानावर जातात. वेगळे वापरण्यासाठी, वरील संपादित करा किंवा काढून टाका.','Kind of storage'=>'स्टोरेजचा प्रकार','Name (for you)'=>'नाव (तुमच्यासाठी)','Provider'=>'प्रदाता','Cloudflare account id'=>'Cloudflare खाते आयडी','Endpoint address'=>'एंडपॉइंट पत्ता','Region'=>'प्रदेश','Bucket'=>'बकेट','Access key id'=>'प्रवेश की आयडी','Secret access key'=>'गुप्त ॲक्सेस की','Leave empty to keep the saved key'=>'जतन केलेली की ठेवण्यासाठी रिक्त सोडा','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Cloudflare R2 साठी: Cloudflare डॅशबोर्डमध्ये R2 उघडा, एक बकेट तयार करा, नंतर “Manage R2 API tokens” → त्या बकेटसाठी Object Read & Write सह टोकन तयार करा, आणि access key id व secret येथे कॉपी करा.','Dropbox app key'=>'Dropbox ॲप की','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'files.content.read, files.content.write आणि files.metadata.read परवानग्यांसह dropbox.com/developers/apps येथे एक ॲप तयार करा (Scoped access, App folder), आणि त्याची App key येथे कॉपी करा. सेव्ह करा, नंतर Connect दाबा.','OAuth client id'=>'OAuth क्लाएंट आयडी','OAuth client secret'=>'OAuth क्लायंट सीक्रेट','Leave empty to keep the saved secret'=>'जतन केलेले सीक्रेट ठेवण्यासाठी रिक्त सोडा','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Google Cloud Console मध्ये, Google Drive API सक्षम करा, नंतर हा पत्ता अधिकृत पुनर्निर्देशन URI म्हणून ठेवून "Web application" प्रकारचा OAuth क्लायंट तयार करा:','Save, then press Connect. The plugin only sees the files it creates.'=>'जतन करा, नंतर कनेक्ट दाबा. प्लगइन केवळ त्याने तयार केलेल्या फायली पाहतो.','Folder inside the storage (optional)'=>'स्टोरेजमधील फोल्डर (पर्यायी)','Save storage'=>'स्टोरेज वाचवा','Import a backup from another plugin or host'=>'दुसऱ्या प्लगइन किंवा होस्टवरून बॅकअप आयात करा','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate किंवा .sql डंप असलेल्या WordPress साइटच्या कोणत्याही zip/tar अर्काइव्हद्वारे तयार केलेल्या बॅकअपमधून साइट आणा. सामग्री wp-content मध्ये जाईल आणि डेटाबेस या साइटच्या डेटाबेसची जागा घेईल; पत्ते आपोआप या साइटच्या पत्त्यांवर बदलले जातील.','Upload from your computer'=>'तुमच्या संगणकावरून अपलोड करा','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'बॅकअपच्या सर्व फाइल्स एकाच वेळी निवडा (UpdraftPlus अनेक फाइल्स तयार करते). मोठ्या फाइल्स छोट्या तुकड्यांमध्ये पाठवल्या जातात, त्यामुळे तुमच्या होस्टची अपलोड मर्यादा लागू होत नाही.','Or from links (Google Drive, Dropbox or any download address)'=>'किंवा लिंक्सवरून (Google Drive, Dropbox किंवा कोणताही डाउनलोड पत्ता)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'प्रत्येक ओळीत एक लिंक. Google Drive आणि Dropbox साठी, फाइल "लिंक असलेल्या कोणाशीही" शेअर करा आणि ती लिंक पेस्ट करा; त्यानंतर शेअरिंग पुन्हा बंद करा.','Or a file already on this server'=>'किंवा या सर्व्हरवर आधीपासून असलेली फाइल','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'FTP किंवा आपल्या होस्टच्या फाइल व्यवस्थापकाद्वारे %s मध्ये संग्रह अपलोड करा आणि हे पृष्ठ रीलोड करा.','Or a deploy code from another site'=>'किंवा दुसऱ्या साइटवरील उपयोजन कोड','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'दुसऱ्या साइटने तुम्हाला Zinn® Backups डिप्लॉय कोड दिला असल्यास, त्याच्या स्टोरेज की शेअर न करता तो बॅकअप या साइटवर कॉपी करण्यासाठी तो येथे पेस्ट करा. कोड काही तास काम करतो; त्याला पासवर्डसारखे हाताळा.','Passphrase (only if that backup is encrypted)'=>'पासफ्रेज (फक्त तो बॅकअप एन्क्रिप्ट केलेला असल्यास)','Import'=>'आयात करा','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'मला समजले आहे की आयात या साइटवरील सामग्री आणि डेटाबेस पुनर्स्थित करते. त्यानंतर, आयात केलेल्या साइटवरील खात्याने साइन इन करा.','Moving to Zinn® hosting?'=>'Zinn® होस्टिंगवर स्थलांतरित होत आहात?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® तुमच्या जुन्या होस्टवरून तुमची साइट तुमच्यासाठी हलवू शकते. तुमचा जुना होस्ट तुम्हाला FTP, SSH किंवा नियंत्रण-पॅनेल प्रवेश देत नसल्यास, जुन्या साइटवर Zinn® Migrate स्थापित करा; हे एक संग्रहण तयार करते जे तुम्ही येथे आयात करू शकता किंवा Zinn® कडे सोपवू शकता.','What goes into a backup'=>'बॅकअपमध्ये काय समाविष्ट असते','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'WordPress च्या स्वतःच्या फाइल्स (wp-admin, wp-includes) समाविष्ट करा. सहसा आवश्यक नसते: WordPress नेहमी पुन्हा स्थापित केले जाऊ शकते.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'तसेच हे फोल्डर्स किंवा फाइल्स वगळा (प्रत्येक ओळीत एक, WordPress फोल्डरच्या सापेक्ष)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'नेहमी वगळले जाते: कॅशे, अपडेट स्क्रॅच स्पेस आणि इतर बॅकअप प्लगइन्सचे स्वतःचे संग्रहण फोल्डर्स:','Size of each part (MB)'=>'प्रत्येक भागाचा आकार (MB)','Save settings'=>'सेटिंग्ज जतन करा','A backup part could not be opened for writing. Check that wp-content has free space.'=>'बॅकअपचा एक भाग लेखनासाठी उघडता आला नाही. wp-content मध्ये मोकळी जागा आहे का ते तपासा.','A backup part could not be written. Check that wp-content has free space.'=>'बॅकअपचा एक भाग लिहिता आला नाही. wp-content मध्ये मोकळी जागा आहे का ते तपासा.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'प्रथम Storage टॅबवर स्टोरेज गंतव्यस्थान कनेक्ट करा: बॅकअप या सर्व्हरवर नाही, तर तुमच्या स्वतःच्या स्टोरेजमध्ये ठेवले जातात.','Multisite networks are not supported yet.'=>'मल्टीसाइट नेटवर्क्स अद्याप समर्थित नाहीत.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'या सर्व्हरच्या PHP मध्ये ZipArchive एक्स्टेंशन नाही. ते सक्षम करण्यासाठी आपल्या होस्टला सांगा.','Starting'=>'सुरू होत आहे','Listing files'=>'फायलींची यादी करत आहे','Backing up the database'=>'डेटाबेसचा बॅकअप घेतला जात आहे','Packing files'=>'फायली पॅक करत आहे','Uploading to your storage'=>'तुमच्या स्टोरेजवर अपलोड होत आहे','Finishing'=>'पूर्ण होत आहे','The backup reached an unknown stage.'=>'बॅकअप एका अज्ञात टप्प्यावर पोहोचला आहे.','Backup %s started.'=>'%s चा बॅकअप सुरू झाला.','Found %1$s files (%2$s).'=>'%1$s फायली आढळल्या (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'डेटाबेस: %1$d तक्ते, %2$s ओळी, %3$s संकुचित.','Backup complete: %1$s stored in %2$d destination.'=>'बॅकअप पूर्ण झाले: %1$s %2$d गंतव्यस्थानात साठवले गेले.' . "\0" . 'बॅकअप पूर्ण: %1$s %2$d स्थानांमध्ये साठवले गेले.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'आधीच अपलोड केलेले काही भाग तुमच्या स्टोरेजमधून काढता आले नाहीत; ते एका अपूर्ण बॅकअप फोल्डरमध्ये आहेत आणि रिस्टोअर करण्यासाठी कधीही उपलब्ध केले जात नाहीत.','A storage destination was removed while the backup was running.'=>'बॅकअप सुरू असताना संचयन गंतव्यस्थान काढले गेले.','That is not a backup folder.'=>'ते बॅकअप फोल्डर नाही.','That storage destination is no longer saved on this site.'=>'ते स्टोरेज गंतव्य आता या साइटवर जतन केलेले नाही.','Later incremental backups are built on this one. Delete those first.'=>'पुढील वाढीव बॅकअप यावर आधारित आहेत. प्रथम ते हटवा.','This file is not an encrypted Zinn® Backups file.'=>'ही फाईल एनक्रिप्ट केलेली Zinn® Backups फाईल नाही.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'बॅकअप डिक्रिप्ट करता आला नाही: पासफ्रेज चुकीचा आहे किंवा फाइल खराब झाली आहे.','The encrypted backup file is incomplete.'=>'कूटबद्ध केलेली बॅकअप फाइल अपूर्ण आहे.','The database file could not be written. Check that wp-content has free space.'=>'डेटाबेस फाइल लिहिता आली नाही. wp-content मध्ये मोकळी जागा आहे का ते तपासा.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'हा उपयोजन कोड नाही. उपयोजन कोड zbdeploy1 ने सुरू होतो.','That deploy code is damaged. Copy it again from the other site.'=>'तो डिप्लॉय कोड खराब झाला आहे. दुसऱ्या साइटवरून तो पुन्हा कॉपी करा.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'डिप्लॉय कोडची मुदत संपली आहे किंवा त्याचा बॅकअप हटवला गेला आहे. दुसऱ्या साइटवर नवीन कोड तयार करा.','That deploy code does not point at a Zinn® Backups backup.'=>'तो डिप्लॉय कोड Zinn® Backups बॅकअपकडे निर्देश करत नाही.','The deploy code has expired. Make a new code on the other site.'=>'डिप्लॉय कोडची मुदत संपली आहे. दुसऱ्या साइटवर नवीन कोड तयार करा.','The server stopped honouring partial downloads. Start the import again.'=>'सर्व्हरने अर्धवट डाउनलोड स्वीकारणे बंद केले आहे. कृपया आयात पुन्हा सुरू करा.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'लिंकने फाइलऐवजी वेब पृष्ठ उघडले. Google Drive आणि Dropbox साठी, फाइल "लिंक असलेल्या कोणाशीही" शेअर करा आणि ती लिंक पेस्ट करा.','The link answered with HTTP %d.'=>'लिंकने HTTP %d सह प्रतिसाद दिला.','The file list could not be written.'=>'फाइल सूची लिहिता आली नाही.','The storage service could not be reached: %s'=>'स्टोरेज सेवेशी संपर्क होऊ शकला नाही: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s ने HTTP %2$d सह उत्तर दिले: %3$s','no details given'=>'कोणताही तपशील दिलेला नाही','You are not allowed to manage backups.'=>'तुम्हाला बॅकअप व्यवस्थापित करण्याची परवानगी नाही.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'पुनर्संचयित केल्याने या साइटच्या फाइल्स आणि डेटाबेस बदलले जातील याची पुष्टी करण्यासाठी बॉक्सवर खूण करा.','Save the destination first.'=>'प्रथम गंतव्य जतन करा.','Connected: a test file was written and removed.'=>'कनेक्ट झाले: चाचणी फाईल लिहिली गेली आणि काढून टाकली गेली.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'प्रथम तुमच्या Dropbox ॲपची ॲप की प्रविष्ट करा (फॉर्मच्या बाजूला असलेल्या पायऱ्या पहा).','This kind of storage does not sign in.'=>'या प्रकारचा स्टोरेज साइन इन करत नाही.','The sign-in expired. Press Connect again.'=>'साइन-इनची मुदत संपली आहे. पुन्हा कनेक्ट करा दाबा.','Dropbox is connected.'=>'Dropbox कनेक्ट केले आहे.','Settings saved.'=>'सेटिंग्ज जतन केल्या.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'दुसरा बॅकअप, पुनर्संचयित करणे किंवा आयात करणे चालू आहे. ते पूर्ण होण्याची प्रतीक्षा करा किंवा ते रद्द करा.','The upload was not started properly. Start again.'=>'अपलोड योग्यरित्या सुरू झाले नाही. कृपया पुन्हा सुरू करा.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'तुकडा पोहोचला नाही. तुमचा सर्व्हर अपलोड आकार मर्यादित करू शकतो; पुन्हा प्रयत्न करा.','Tick the box to confirm that the import replaces this site’s content and database.'=>'आयात या साइटची सामग्री आणि डेटाबेस पुनर्स्थित करते याची पुष्टी करण्यासाठी बॉक्सवर खूण करा.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'आयात करण्यासाठी एक संग्रह निवडा: तो अपलोड करा, लिंक पेस्ट करा किंवा आयात फोल्डरमधून एक निवडा.','Hosting customer? Get %1$d%% off %2$s'=>'होस्टिंग ग्राहक आहात? %2$s वर %1$d%% सूट मिळवा','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Zinn Digital® होस्टिंग ग्राहक म्हणून तुम्हाला तुमच्या पहिल्या पेमेंटवर %d%% सवलतीसाठी वैयक्तिक कोड मिळतो. नूतनीकरण सामान्य किमतीत होते.','Get my %d%% code and go to checkout'=>'माझा %d%% कोड मिळवा आणि चेकआउटवर जा','Sorry, you are not allowed to do that.'=>'क्षमस्व, आपल्याला हे करण्याची परवानगी नाही.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'ही सवलत चांगल्या स्थितीत सशुल्क होस्टिंग योजना असलेल्या ग्राहकांसाठी आहे. विनामूल्य चाचण्या पात्र नाहीत.','You have already used your hosting-customer discount for this plugin.'=>'तुम्ही या प्लगइनसाठी तुमची होस्टिंग-ग्राहक सवलत आधीच वापरली आहे.','We could not get your code just now. Please try again in a few minutes.'=>'आम्हाला आत्ताच तुमचा कोड मिळू शकला नाही. कृपया काही मिनिटांत पुन्हा प्रयत्न करा.','Reading the backup'=>'बॅकअप वाचत आहे','Downloading the archive'=>'संग्रह डाउनलोड करत आहे','Recognising the archive'=>'संग्रह ओळखत आहे','Restoring files'=>'फायली पुनर्संचयित करत आहे','Downloading the database'=>'डेटाबेस डाउनलोड होत आहे','Restoring the database'=>'डेटाबेस पुनर्संचयित करत आहे','Updating the site address'=>'साइटचा पत्ता अपडेट करत आहे','Switching to the restored database'=>'पुनर्संचयित डेटाबेसवर स्विच करत आहे','The restore reached an unknown stage.'=>'पुनर्संचयन एका अज्ञात टप्प्यावर पोहोचले.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'या फोल्डरमध्ये कोणताही पूर्ण Zinn® Backups बॅकअप नाही (मॅनिफेस्ट गहाळ आहे).','This backup is encrypted. Enter its passphrase to restore it.'=>'हा बॅकअप एनक्रिप्ट केलेला आहे. तो पुनर्संचयित करण्यासाठी त्याचा पासफ्रेज प्रविष्ट करा.','This incremental backup needs backup %s, which is no longer in the storage.'=>'या वाढीव बॅकअपसाठी %s हा बॅकअप आवश्यक आहे, जो आता स्टोरेजमध्ये उपलब्ध नाही.','Restoring the backup of %1$s (%2$d file parts).'=>'%1$s चा बॅकअप पुनर्संचयित करत आहे (%2$d फाइल भाग).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'%1$s फाइल पुनर्लेखित केली जाऊ शकली नाही कारण या साइटला ती बदलण्याची परवानगी नाही आणि ती जशी आहे तशीच ठेवली गेली: %2$s' . "\0" . 'या साइटला त्या फायली बदलण्याची परवानगी नसल्यामुळे %1$s फायली पुनर्लेखन करता आल्या नाहीत, आणि त्या तशाच ठेवल्या गेल्या: %2$s','Restored %s files.'=>'%s फायली पुनर्संचयित केल्या.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'डाउनलोड केल्यानंतर %s त्याच्या चेकसमशी जुळला नाही. स्टोरेजमधील प्रत खराब झालेली असू शकते.','%s did not arrive. Upload it again.'=>'%s आले नाही. कृपया ते पुन्हा अपलोड करा.','Recognised: %s.'=>'ओळखले: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'wp-content मध्ये %1$s फाइल्स आयात केल्या (%2$s वगळल्या: कॅशे, drop-ins आणि इतर बॅकअप प्लगइन्सचे फोल्डर्स).','The archive has no database dump, so only files were imported.'=>'संग्रहात कोणताही डेटाबेस डंप नाही, म्हणून केवळ फाइल्स आयात केल्या गेल्या.','Database restored into %d temporary tables.'=>'डेटाबेस %d तात्पुरत्या तक्त्यांमध्ये पुनर्संचयित केला गेला.','%s has no WordPress tables in it and was skipped.'=>'%s मध्ये कोणतेही WordPress तक्ते नाहीत आणि ते वगळले गेले.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'बॅकअपच्या डेटाबेसमध्ये कोणतेही WordPress टेबल्स नाहीत, त्यामुळे काहीही बदलले गेले नाही.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'हा बॅकअप एका मल्टीसाइट नेटवर्कचा आहे. नेटवर्क एकाच साइटवर पुनर्संचयित करण्यास समर्थन नाही.','Moving the content from %1$s to %2$s.'=>'%1$s वरून %2$s वर मजकूर हलवत आहे.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'पुनर्संचयन पूर्ण झाले. आपण साइन आउट झाले असल्यास, पुनर्संचयित साइटवरील खात्यासह साइन इन करा.','Restore complete.'=>'पुनर्संचयन पूर्ण झाले.','%1$s — trying again in %2$d seconds.'=>'%1$s — %2$d सेकंदांत पुन्हा प्रयत्न करत आहे.','Cancelled.'=>'रद्द केले.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'बॅकअप एका स्टोरेज गंतव्यावर जातात. वेगळे वापरण्यासाठी तुमच्याकडे असलेले संपादित करा किंवा काढून टाका.','The database file could not be opened.'=>'डेटाबेस फाइल उघडता आली नाही.','The database refused a statement from the backup: %1$s (%2$s…)'=>'डेटाबेसने बॅकअपमधील स्टेटमेंट नाकारले: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'पुनर्संचयित केलेले तक्ते बदलता आले नाहीत: %s. तुमची साइट अपरिवर्तित आहे.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'तात्पुरत्या बॅकअप फाइल्ससाठी कोणतीही लिहिता येण्याजोगी फोल्डर उपलब्ध नाही. wp-content लिहिता येण्याजोगे करा आणि पुन्हा प्रयत्न करा.','Could not create a folder for this job.'=>'या कार्यासाठी फोल्डर तयार करता आले नाही.','%s — guides and services'=>'%s — मार्गदर्शक आणि सेवा','User guides'=>'वापरकर्ता मार्गदर्शिका','Read the %s user guide'=>'%s वापरकर्ता मार्गदर्शक वाचा','Hide this'=>'हे लपवा','Zinn® hosting for WordPress'=>'WordPress साठी Zinn® होस्टिंग','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक बॅकअप, विनामूल्य स्थलांतर आणि एकापेक्षा जास्त साइट चालवणाऱ्या लोकांसाठी तयार केलेले नियंत्रण पॅनेल.','The Zinn® marketplace'=>'Zinn® मार्केटप्लेस','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'दोन्ही बाजू समाधानी होईपर्यंत पैसे सुरक्षित ठेवून, प्रस्थापित साइट्स, डोमेन्स आणि लिंक प्लेसमेंट्स खरेदी आणि विक्री करा.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — हा ज्यांचा व्यवसाय आहे अशा लोकांना कामावर घ्या','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'आमची जागतिक फ्रीलान्स बाजारपेठ: लेखक, डिझायनर्स, डेव्हलपर्स आणि SEO तज्ज्ञांच्या १०,००० हून अधिक तयार सेवा ब्राउझ करा, किंवा एखादा प्रकल्प पोस्ट करा आणि त्यांना बोली लावू द्या.','See the Zinn Digital® release notes.'=>'Zinn Digital® प्रकाशन टिपा पहा.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® अपडेट सेवेने या अपडेटसाठी डाउनलोड लिंक जारी केली नाही. ही साइट Zinn® प्लॅटफॉर्मपर्यंत पोहोचू शकते का ते तपासा, नंतर पुन्हा प्रयत्न करा.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® अपडेट सेवेवरून (%s) अपडेट डाउनलोड करता आले नाही. कृपया काही मिनिटांनंतर पुन्हा प्रयत्न करा.','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड केलेले अपडेट अखंडता तपासणीत अयशस्वी झाले आणि स्थापित केले गेले नाही.','The zip archive could not be opened. It may be damaged or incomplete.'=>'झिप संग्रहण उघडता आले नाही. ते खराब झालेले किंवा अपूर्ण असू शकते.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'ही .wpress फाईल आम्ही वाचू शकत नसलेले स्वरूप वापरते (हे All-in-One WP Migration द्वारे संकुचित किंवा एनक्रिप्ट केलेले असू शकते). कृपया एनक्रिप्शनशिवाय ते पुन्हा निर्यात करा.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'ही एक Duplicator “DupArchive” (.daf) फाइल आहे. Duplicator मध्ये, आर्काइव्ह स्वरूप ZIP वर सेट करून पॅकेज पुन्हा तयार करा, नंतर ते आयात करा.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'हा UpdraftPlus डेटाबेस बॅकअप एन्क्रिप्ट केलेला आहे. UpdraftPlus मध्ये तो डिक्रिप्ट करा (किंवा डेटाबेस एन्क्रिप्शन बंद करा आणि पुन्हा बॅकअप घ्या), नंतर तो आयात करा.','Database dump'=>'डेटाबेस डम्प','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s हे आम्ही वाचू शकू असे बॅकअप संग्रहण नाही (zip, tar, tar.gz, .wpress, .sql किंवा .sql.gz).','Website archive'=>'वेबसाइट संग्रह','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s मध्ये कोणतीही WordPress सामग्री नाही (कोणतेही wp-content फोल्डर नाही आणि डेटाबेस डंप नाही).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'ही .wpress फाईल All-in-One WP Migration द्वारे एनक्रिप्ट किंवा कॉम्प्रेस केलेली आहे. कृपया एनक्रिप्शन आणि कॉम्प्रेशन बंद करून ती पुन्हा निर्यात करा, नंतर ती आयात करा.','Other S3-compatible storage'=>'इतर S3-सुसंगत स्टोरेज','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 किंवा S3-सुसंगत','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'या साइटवर स्टोरेज की वाचता आल्या नाहीत. स्टोरेज टॅबवर गुप्त की पुन्हा प्रविष्ट करा.','This kind of storage is not known.'=>'या प्रकारचा स्टोरेज माहित नाही.','Choose a kind of storage.'=>'स्टोरेजचा प्रकार निवडा.','Enter the bucket name and the access key.'=>'बकेटचे नाव आणि प्रवेश की प्रविष्ट करा.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'तुमचा Cloudflare खाते आयडी (किंवा संपूर्ण R2 एंडपॉइंट) प्रविष्ट करा.','Enter the endpoint address of your storage.'=>'तुमच्या स्टोरेजचा एंडपॉइंट पत्ता प्रविष्ट करा.','Enter the OAuth client id from your Google Cloud project.'=>'तुमच्या Google Cloud प्रकल्पातील OAuth client id प्रविष्ट करा.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox ने रिफ्रेश टोकन परत केले नाही. कृपया कनेक्शन पुन्हा सुरू करा.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox कनेक्ट केलेले नाही. स्टोरेज टॅबवर ते पुन्हा कनेक्ट करा.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google ने रीफ्रेश टोकन परत केले नाही. ही साइट तुमच्या Google खात्याच्या तृतीय-पक्ष ॲक्सेसमधून काढून टाका आणि पुन्हा कनेक्ट करा.','That file is not in Google Drive any more.'=>'ती फाइल आता Google Drive मध्ये नाही.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive जोडलेले नाही. स्टोरेज टॅबवर ते पुन्हा जोडा.','The storage service did not start the upload.'=>'स्टोरेज सेवेने अपलोड सुरू केले नाही.','The storage service sent a reply that could not be read.'=>'स्टोरेज सेवेने असा प्रतिसाद पाठवला आहे जो वाचता आला नाही.','A temporary backup file could not be read.'=>'तात्पुरती बॅकअप फाइल वाचता आली नाही.','A deploy link is read-only.'=>'डिप्लॉय लिंक केवळ वाचण्यासाठी आहे.','The deploy code has no link for a file this backup needs.'=>'डिप्लॉय कोडमध्ये या बॅकअपसाठी आवश्यक असलेल्या फाइलसाठी कोणतीही लिंक नाही.','The deploy link'=>'डिप्लॉय लिंक']];